local BeardCombMaker = {}
local PRODUCTS = {
    iron_beard_comb = { name = "Železni glavnik za brado", ironCost = 2, woodCost = 2, leatherCost = 1, time = 4, cost = 120, prestige = 3, happiness = 2, description = "Železni glavnik za nego brade." },
    bronze_beard_comb = { name = "Bronast glavnik za brado", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 6, cost = 300, prestige = 5, happiness = 3, description = "Bronast glavnik za negovano brado." },
    silver_beard_comb = { name = "Srebrni glavnik za brado", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 10, cost = 740, prestige = 10, happiness = 4, description = "Srebrni glavnik za plemiške brade." },
    gilded_beard_comb = { name = "Pozlačeni glavnik za brado", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 14, cost = 1620, prestige = 19, happiness = 5, description = "Pozlačeni glavnik za dvorne brade." },
    jewel_set_beard_comb = { name = "Draguljasti glavnik za brado", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 18, cost = 3550, prestige = 35, happiness = 7, description = "Draguljasti glavnik za kraljeve brade." },
    royal_sovereign_beard_comb = { name = "Kraljevski suvereni glavnik za brado", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 25, cost = 7900, prestige = 67, happiness = 13, description = "Suvereni glavnik z biseri za krono." },
}
local BUILDINGS = {
    beardcomb_workshop = { name = "Bradna delavnica", cost = { gold = 290, wood = 175, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    beardcomb_house = { name = "Bradna hiša", cost = { gold = 1080, wood = 350, stone = 250, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_beardcomb_atelier = { name = "Mojstrski bradni atelje", cost = { gold = 2850, wood = 410, stone = 490, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_beardcomb_palace = { name = "Suverena bradna palača", cost = { gold = 12400, wood = 635, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
BeardCombMaker.ironStock = 12; BeardCombMaker.bronzeStock = 10; BeardCombMaker.woodStock = 16; BeardCombMaker.leatherStock = 8; BeardCombMaker.silverStock = 8; BeardCombMaker.goldStock = 6; BeardCombMaker.jewelStock = 4; BeardCombMaker.pearlStock = 4
BeardCombMaker.productStock = {}; BeardCombMaker.buildings = {}; BeardCombMaker.maker = nil; BeardCombMaker.activeMaking = {}; BeardCombMaker.totalProducts = 0; BeardCombMaker.dayTimer = 0
function BeardCombMaker.init() BeardCombMaker.ironStock=12; BeardCombMaker.bronzeStock=10; BeardCombMaker.woodStock=16; BeardCombMaker.leatherStock=8; BeardCombMaker.silverStock=8; BeardCombMaker.goldStock=6; BeardCombMaker.jewelStock=4; BeardCombMaker.pearlStock=4; BeardCombMaker.productStock={}; BeardCombMaker.buildings={}; BeardCombMaker.maker=nil; BeardCombMaker.activeMaking={}; BeardCombMaker.totalProducts=0; BeardCombMaker.dayTimer=0; print("[BeardCombMaker] Royal Beard Comb Maker System initialized (6 products, 4 buildings)") end
function BeardCombMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BeardCombMaker.maker={name=n or ("Bradar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bradar najet: %s (spretnost: %d)",BeardCombMaker.maker.name,s),"success") end; return true end
function BeardCombMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BeardCombMaker.build(id) local ok,e=BeardCombMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BeardCombMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BeardCombMaker.getQualityBonus() local b=0; for _,bd in ipairs(BeardCombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BeardCombMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BeardCombMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BeardCombMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BeardCombMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BeardCombMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BeardCombMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BeardCombMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BeardCombMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BeardCombMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BeardCombMaker.buildings==0 then return false,"Potrebna bradna delavnica" end; if not BeardCombMaker.maker then return false,"Potreben bradar" end; return true end
function BeardCombMaker.make(pt,qty) qty=qty or 1; local ok,e=BeardCombMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BeardCombMaker.ironStock=BeardCombMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BeardCombMaker.bronzeStock=BeardCombMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BeardCombMaker.woodStock=BeardCombMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BeardCombMaker.leatherStock=BeardCombMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BeardCombMaker.silverStock=BeardCombMaker.silverStock-d.silverCost*qty end; if d.goldCost then BeardCombMaker.goldStock=BeardCombMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BeardCombMaker.jewelStock=BeardCombMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BeardCombMaker.pearlStock=BeardCombMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BeardCombMaker.maker then t=math.max(1,t-math.floor(BeardCombMaker.maker.skill/13)) end; table.insert(BeardCombMaker.activeMaking,{id="beardcomb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BeardCombMaker.completeMaking(m) local q=1.0+(BeardCombMaker.getQualityBonus()/100); if BeardCombMaker.maker then q=q+(BeardCombMaker.maker.skill/140) end; q=math.min(2.5,q); BeardCombMaker.productStock[m.productType]=(BeardCombMaker.productStock[m.productType] or 0)+m.quantity; BeardCombMaker.totalProducts=BeardCombMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BeardCombMaker.maker then BeardCombMaker.maker.itemsMade=BeardCombMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BeardCombMaker.maker.skill=math.min(100,BeardCombMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bradni glavnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"beardcomb.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BeardCombMaker.update(dt) if not _G.state then return end; BeardCombMaker.dayTimer=BeardCombMaker.dayTimer+dt; if BeardCombMaker.dayTimer>=30 then BeardCombMaker.dayTimer=0; for i=#BeardCombMaker.activeMaking,1,-1 do local m=BeardCombMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BeardCombMaker.completeMaking(m); table.remove(BeardCombMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BeardCombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BeardCombMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BeardCombMaker.getStats() return {ironStock=BeardCombMaker.ironStock,bronzeStock=BeardCombMaker.bronzeStock,woodStock=BeardCombMaker.woodStock,leatherStock=BeardCombMaker.leatherStock,silverStock=BeardCombMaker.silverStock,goldStock=BeardCombMaker.goldStock,jewelStock=BeardCombMaker.jewelStock,pearlStock=BeardCombMaker.pearlStock,productStock=BeardCombMaker.productStock,numBuildings=#BeardCombMaker.buildings,hasMaker=BeardCombMaker.maker~=nil,makerName=BeardCombMaker.maker and BeardCombMaker.maker.name or "—",makerSkill=BeardCombMaker.maker and BeardCombMaker.maker.skill or 0,activeMaking=#BeardCombMaker.activeMaking,totalProducts=BeardCombMaker.totalProducts} end
return BeardCombMaker
